from __future__ import annotations

from typing import Any
import numpy as np
from scipy import signal
from functools import lru_cache


@lru_cache(maxsize=256)
def _foh_tf_cached(num_key, den_key, dt_key):
    """Return discrete FOH transfer-function coefficients for lsim-equivalent simulation."""
    num = np.asarray(num_key, dtype=float)
    den = np.asarray(den_key, dtype=float)
    dt = float(dt_key)
    # cont2discrete for transfer functions performs the same first-order-hold
    # discretization as lsim(interp=True), but yields a discrete filter that can
    # be evaluated by scipy's C lfilter instead of Python state looping.
    bd, ad, _ = signal.cont2discrete((num, den), dt, method="foh")
    return np.ravel(bd).astype(float), np.ravel(ad).astype(float)


def _key_from_arr(a):
    arr = np.asarray(a, dtype=float).ravel()
    return tuple(float(x) for x in arr)


class Solver:
    def solve(self, problem, **kwargs) -> Any:
        num_in = problem["num"]
        den_in = problem["den"]
        u_in = problem["u"]
        t_in = problem["t"]

        # Convert only once.  The inputs are normally lists/1-D arrays.
        u = np.asarray(u_in, dtype=float).ravel()
        t = np.asarray(t_in, dtype=float).ravel()
        n = t.size

        if n == 0:
            return {"yout": []}

        # With zero initial state, zero input gives identically zero output.
        # This also avoids all scipy setup for a common benchmark case.
        if u.size == n and not np.any(u):
            return {"yout": [0.0] * int(n)}

        num = np.asarray(num_in, dtype=float).ravel()
        den = np.asarray(den_in, dtype=float).ravel()

        # For a single time point, scipy.signal.lsim returns D*u[0] (zero IC).
        if n == 1:
            try:
                # direct feedthrough term of a proper transfer function after
                # scipy's normalization convention.  Strictly proper => 0.
                if num.size == den.size:
                    d = (num[0] / den[0])
                elif num.size > den.size:
                    # Improper TF; let scipy handle/raise consistently.
                    _, y, _ = signal.lsim(signal.lti(num, den), u, t)
                    return {"yout": np.asarray(y, dtype=float).ravel().tolist()}
                else:
                    d = 0.0
                val = float(d * (u[0] if u.size else 0.0))
                return {"yout": [val]}
            except Exception:
                _, y, _ = signal.lsim(signal.lti(num, den), u, t)
                return {"yout": np.asarray(y, dtype=float).ravel().tolist()}

        try:
            dt = float(t[1] - t[0])
            # For constant/static gains scipy's state-space path can be more
            # awkward; lfilter route still works for proper TFs, but direct is
            # fastest when both polynomials are constants.
            if den.size == 1 and num.size == 1:
                gain = float(num[0] / den[0])
                return {"yout": (gain * u).tolist()}

            b, a = _foh_tf_cached(_key_from_arr(num), _key_from_arr(den), dt)
            y = signal.lfilter(b, a, u)
            return {"yout": np.asarray(y, dtype=float).ravel().tolist()}
        except Exception:
            # Safety fallback: exact reference algorithm for unusual inputs.
            system = signal.lti(num, den)
            _, yout, _ = signal.lsim(system, u, t)
            return {"yout": np.asarray(yout, dtype=float).ravel().tolist()}
